package com.gwtplatform.carstore.client.place;

public class NameTokens {
    public static final String UNAUTHORIZED = "unauthorized";
    public static final String LOGIN = "login";
    public static final String MANUFACTURER = "manufacturer";
    public static final String DETAIL_MANUFACTURER = "detailManufacturer";
    public static final String RATING = "rating";
    public static final String DETAIL_RATING = "detailRating";
    public static final String CARS = "cars";
    public static final String REPORT = "report";
    public static final String NEW_CAR = "newCar";
    public static final String STATS = "stats";

    public static String getOnLoginDefaultPage() {
        return MANUFACTURER;
    }

    public static String getManufacturer() {
        return MANUFACTURER;
    }

    public static String getDetailManufacturer() {
        return DETAIL_MANUFACTURER;
    }

    public static String getRating() {
        return RATING;
    }

    public static String getDetailRating() {
        return DETAIL_RATING;
    }

    public static String getCars() {
        return CARS;
    }

    public static String getReport() {
        return REPORT;
    }
}
<ui:UiBinder xmlns:ui='urn:ui:com.google.gwt.uibinder'
             xmlns:g='urn:import:com.google.gwt.user.client.ui'
             xmlns:cell="urn:import:com.google.gwt.user.cellview.client">
    <ui:with field="resources" type="com.gwtplatform.carstore.client.resources.AppResources"/>
    <ui:import field="com.gwtplatform.carstore.client.debug.DebugIds.*"/>
    <ui:style>
        .tableWrapper {
            margin-top: 20px;
        }
    </ui:style>
    <g:HTMLPanel>
        <div class="{resources.styles.bigTitle}">
            <h2>
                <g:InlineLabel text="Manufacturers"/>
            </h2>
            <div>
                <g:Button ui:field="create" styleName="{resources.styles.addAction}" debugId="{DBG_CREATE_MANUFACTURER}"/>
            </div>
            <span style="display: block; clear: both;"/>
        </div>
        <div class="{style.tableWrapper}">
            <cell:CellTable ui:field="manufacturerGrid" width="100%" debugId="{DBG_MANUFACTURERS}"/>
        </div>
    </g:HTMLPanel>
</ui:UiBinder>
<ui:UiBinder xmlns:ui="urn:ui:com.google.gwt.uibinder" xmlns:g="urn:import:com.google.gwt.user.client.ui">
    <ui:import field="com.gwtplatform.carstore.client.debug.DebugIds.*"/>
    <g:PopupPanel glassEnabled="true" autoHideEnabled="true" animationEnabled="true">
        <g:HTMLPanel debugId="{DBG_MANUFACTURER_EDITOR}">
            <div>
                <g:InlineLabel>Name:</g:InlineLabel>
                <g:TextBox ui:field="name" debugId="{DBG_MANUFACTURER_INPUT}"/>
            </div>
            <div>
                <g:Button ui:field="save" debugId="{DBG_MANUFACTURER_SAVE}">Save</g:Button>
                <g:Button ui:field="close" debugId="{DBG_MANUFACTURER_CLOSE}">Close</g:Button>
            </div>
        </g:HTMLPanel>
    </g:PopupPanel>
</ui:UiBinder>
<ui:UiBinder xmlns:ui='urn:ui:com.google.gwt.uibinder'
             xmlns:g='urn:import:com.google.gwt.user.client.ui'
             xmlns:cell="urn:import:com.google.gwt.user.cellview.client">
    <ui:with field="resources" type="com.gwtplatform.carstore.client.resources.AppResources"/>
    <ui:import field="com.gwtplatform.carstore.client.debug.DebugIds.*"/>
    <ui:style>
        .tableWrapper {
            margin-top: 20px;
        }
    </ui:style>
    <g:HTMLPanel>
        <div class="{resources.styles.bigTitle}">
            <h2>
                <g:InlineLabel text="Ratings"/>
            </h2>
            <div>
                <g:Button ui:field="create" debugId="{DBG_RATING_CREATE}" styleName="{resources.styles.addAction}"/>
            </div>
            <span style="display: block; clear: both;"/>
        </div>
        <div class="{style.tableWrapper}">
            <cell:CellTable ui:field="ratingGrid" width="100%" debugId="{DBG_RATINGS}"/>
        </div>
    </g:HTMLPanel>
</ui:UiBinder>
<ui:UiBinder xmlns:ui="urn:ui:com.google.gwt.uibinder" xmlns:g="urn:import:com.google.gwt.user.client.ui">
    <ui:import field="com.gwtplatform.carstore.client.debug.DebugIds.*"/>
    <g:PopupPanel glassEnabled="true" autoHideEnabled="true" animationEnabled="true">
        <g:HTMLPanel>
            <div>
                <g:InlineLabel>Car:</g:InlineLabel>
                <g:ValueListBox ui:field="car"/>
            </div>
            <div>
                <g:InlineLabel>Your rating:</g:InlineLabel>
                <g:IntegerBox ui:field="rating" maxLength="3" debugId="{DBG_RATING_INPUT}"/>
            </div>
            <div>
                <g:Button ui:field="save" debugId="{DBG_RATING_SAVE}">Save</g:Button>
                <g:Button ui:field="close">Close</g:Button>
            </div>
        </g:HTMLPanel>
    </g:PopupPanel>
</ui:UiBinder>
<ui:UiBinder xmlns:ui='urn:ui:com.google.gwt.uibinder'
             xmlns:g='urn:import:com.google.gwt.user.client.ui'
             xmlns:cell="urn:import:com.google.gwt.user.cellview.client">
    <ui:with field="resources" type="com.gwtplatform.carstore.client.resources.AppResources"/>
    <ui:import field="com.gwtplatform.carstore.client.debug.DebugIds.*"/>
    <ui:style>
        .tableWrapper {
            margin-top: 20px;
        }
    </ui:style>
    <g:HTMLPanel>
        <div class="{resources.styles.bigTitle}">
            <h2>
                <g:InlineLabel text="Average Car Rating by Manufacturer"/>
            </h2>
            <span style="display: block; clear: both;"/>
        </div>
        <div class="{style.tableWrapper}">
            <cell:CellTable ui:field="reportGrid" width="100%" debugId="{DBG_REPORTS}"/>
        </div>
    </g:HTMLPanel>
</ui:UiBinder>
<ui:UiBinder xmlns:ui='urn:ui:com.google.gwt.uibinder'
             xmlns:g='urn:import:com.google.gwt.user.client.ui'>
    <ui:import field="com.gwtplatform.carstore.client.place.NameTokens.*"/>
    <ui:import field="com.gwtplatform.carstore.client.debug.DebugIds.*"/>
    <ui:with field="resource" type="com.gwtplatform.carstore.client.resources.AppResources"/>
    <ui:style>
        .header {
            border-bottom: 1px solid #45a0ec;
        }
        .headerContent {
            width: 1000px;
            margin: 0px auto;
            padding: 5px 0px;
        }
        .applicationTitle {
            padding-top: 10px;
            font-size: 16px;
            font-weight: bold;
            padding-left: 10px;
            padding-top: 15px;
        }
        .userInfo {
            float: left;
            padding-top: 6px;
            padding-right: 20px;
            margin-right: 11px;
            border-right: 1px solid #aeaeae;
        }
        .userName {
            font-weight: bold;
        }
        .logoutButton {
            background: none;
            border: none;
            color: #45a0ec;
            font-size: 14px;
        }
        .logoutButton:hover {
            text-decoration: underline;
            color: #1d6098;
        }
        .menuBarWrapper {
            margin-left: 30px;
            padding-top: 10px;
        }
        .floatLeft {
            float: left;
        }
        .floatRight {
            float: right;
        }
        .paddingTop {
            margin-top: 10px;
        }
        .clear {
            clear: both;
        }
    </ui:style>
    <g:HTMLPanel styleName="{style.header}">
        <div class="{style.headerContent}">
            <div class="{style.floatLeft}">
                <g:Image resource="{resource.logo}"/>
            </div>
            <div class="{style.floatLeft} {style.applicationTitle}">
                <g:Label text="CarStore"/>
            </div>
            <g:HTMLPanel styleName="{style.floatLeft} {style.menuBarWrapper}" ui:field="menubar" debugId="{DBG_MENUBAR}">
                <g:InlineHyperlink targetHistoryToken="{MANUFACTURER}">Manufacturers</g:InlineHyperlink>
                <g:InlineHyperlink targetHistoryToken="{CARS}">Cars</g:InlineHyperlink>
                <g:InlineHyperlink targetHistoryToken="{RATING}">Ratings</g:InlineHyperlink>
                <g:InlineHyperlink targetHistoryToken="{REPORT}">Reports</g:InlineHyperlink>
                <g:InlineHyperlink targetHistoryToken="{STATS}">Statistics</g:InlineHyperlink>
            </g:HTMLPanel>
            <g:HTMLPanel ui:field="userOptions" styleName="{style.floatRight} {style.paddingTop}">
                <div class="{style.userInfo}">
                    Hello
                    <g:InlineLabel ui:field="name" styleName="{style.userName}"/>
                    !
                </div>
                <div class="{style.floatLeft}">
                    <g:Button ui:field="logout" debugId="{DBG_LOGOUT}" text="Logout"
                              styleName="{style.logoutButton}"/>
                </div>
                <div class="{style.clear}"/>
            </g:HTMLPanel>
            <div class="{style.clear}"/>
        </div>
    </g:HTMLPanel>
</ui:UiBinder>
<ui:UiBinder xmlns:ui='urn:ui:com.google.gwt.uibinder' xmlns:g="urn:import:com.google.gwt.user.client.ui">
    <ui:with field="appResources" type="com.gwtplatform.carstore.client.resources.AppResources"/>
    <g:HTMLPanel ui:field="messageBox" styleName="{appResources.styles.message}" visible="false">
        <g:InlineLabel ui:field="messageLabel"/>
        <g:InlineHTML ui:field="close" styleName="{appResources.styles.close}">X</g:InlineHTML>
    </g:HTMLPanel>
</ui:UiBinder>

