export interface Message { id: number; text: string; style: 'success' | 'error'; }

@Injectable({ providedIn: 'root' })
export class MessageService {
  messages: Message[] = [];
  private next = 1;
  show(text: string, style: 'success' | 'error' = 'success'): void {
    const m: Message = { id: this.next++, text, style };
    this.messages.push(m);
    setTimeout(() => this.close(m), 5000);
  }
  error(text: string): void { this.show(text, 'error'); }
  close(m: Message): void { this.messages = this.messages.filter(x => x !== m); }
}
