export class ManufacturerComponent implements OnInit {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  items: ManufacturerDto[] = [];
  editing: ManufacturerDto | null = null;
  private original: ManufacturerDto | null = null;

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({ next: l => this.items = l, error: () => this.msg.error('Failed to load manufacturers') });
  }
  create(): void { this.original = null; this.editing = { name: '' }; }
  edit(m: ManufacturerDto): void { this.original = m; this.editing = { ...m }; }
  close(): void { this.editing = null; }
