    this.api.saveManufacturer(this.editing).subscribe({
      next: saved => {
        if (this.original) {
          this.items = this.items.map(x => x === this.original ? saved : x);
        } else {
          this.items = [...this.items, saved];
        }
        this.msg.show('Manufacturer saved');
        this.editing = null;
      },
      error: () => this.msg.error('Failed to save manufacturer'),
    });
