import { Component, OnInit, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService, ManufacturerDto } from './api.service';
import { MessageService } from './message.service';

@Component({
  selector: 'app-manufacturer',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="bigTitle">
      <h2>Manufacturers</h2>
      <button id="gwt-debug-create-manufacturer" class="addAction" (click)="create()">Create</button>
    </div>
    <table id="gwt-debug-manufacturers" class="grid">
      <thead><tr><th>ID</th><th>Name</th><th>Edit</th><th>Delete</th></tr></thead>
      <tbody>
        @for (m of items; track m.id) {
          <tr>
            <td>{{ m.id }}</td><td>{{ m.name }}</td>
            <td><button (click)="edit(m)">Edit</button></td>
            <td><button (click)="remove(m)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>
    @if (editing) {
      <div class="glass"></div>
      <div class="popup" id="gwt-debug-manufacturer-editor">
        <div><span>Name:</span> <input id="gwt-debug-manufacturer-input" [(ngModel)]="editing.name"></div>
        <div>
          <button id="gwt-debug-manufacturer-save" (click)="save()">Save</button>
          <button id="gwt-debug-manufacturer-close" (click)="close()">Close</button>
        </div>
      </div>
    }`,
})
export class ManufacturerComponent implements OnInit {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  items: ManufacturerDto[] = [];
  editing: ManufacturerDto | null = null;
  private original: ManufacturerDto | null = null;

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({ next: l => this.items = l, error: () => this.msg.error('Failed to load manufacturers') });
  }
  create(): void { this.original = null; this.editing = { name: '' }; }
  edit(m: ManufacturerDto): void { this.original = m; this.editing = { ...m }; }
  close(): void { this.editing = null; }
  save(): void {
    if (!this.editing) { return; }
    this.api.saveManufacturer(this.editing).subscribe({
      next: saved => {
        if (this.original) {
          this.items = this.items.map(x => x === this.original ? saved : x);
        } else {
          this.items = [...this.items, saved];
        }
        this.msg.show('Manufacturer saved');
        this.editing = null;
      },
      error: () => this.msg.error('Failed to save manufacturer'),
    });
  }
  remove(m: ManufacturerDto): void {
    if (!window.confirm('Are you sure you want to delete ' + m.name + '?')) { return; }
    this.api.deleteManufacturer(m.id as number).subscribe({
      next: () => this.items = this.items.filter(x => x !== m),
      error: () => this.msg.error('Failed to delete manufacturer'),
    });
  }
}
